// Extraction of strictly validated commands for POST /api/run
const text = ($json.message && $json.message.text) ? $json.message.text.trim() : '';
const chatId = ($json.message && $json.message.chat) ? String($json.message.chat.id).trim() : '';

// 1. Default action: CHAT (natural conversation)
let action = 'chat';
let preset = 'standard';
let repo = '';
let cleanText = text;

// Explicit action detection
if (cleanText.startsWith('/task') || cleanText.startsWith('/develop') || cleanText.startsWith('/sviluppa')) {
  action = 'execute_task';
  cleanText = cleanText.replace(/^\/(task|develop|sviluppa)\s*/i, '').trim();
} else if (cleanText.startsWith('/brainstorm')) {
  action = 'brainstorm';
  preset = 'critical';
  cleanText = cleanText.replace(/^\/brainstorm\s*/i, '').trim();
} else if (cleanText.startsWith('/approve')) {
  action = 'approve';
  cleanText = cleanText.replace(/^\/approve\s*/i, '').trim();
} else if (cleanText.startsWith('/reject')) {
  action = 'reject';
  cleanText = cleanText.replace(/^\/reject\s*/i, '').trim();
} else if (cleanText.startsWith('/clear')) {
  action = 'clear';
  cleanText = cleanText.replace(/^\/clear\s*/i, '').trim();
} else if (cleanText.startsWith('/chat')) {
  action = 'chat';
  cleanText = cleanText.replace(/^\/chat\s*/i, '').trim();
}

// 2. Allowed presets (standard, critical, light, luna_flash)
if (cleanText.includes('--critical') || cleanText.startsWith('/critical')) {
  preset = 'critical';
  cleanText = cleanText.replace('/critical', '').replace('--critical', '');
} else if (cleanText.includes('--light') || cleanText.startsWith('/light')) {
  preset = 'light';
  cleanText = cleanText.replace('/light', '').replace('--light', '');
} else if (cleanText.includes('--luna_flash') || cleanText.startsWith('/luna_flash')) {
  preset = 'luna_flash';
  cleanText = cleanText.replace('/luna_flash', '').replace('--luna_flash', '');
}

// 3. Repo catalog alias extraction (e.g. repo:myproject)
const words = cleanText.split(/\s+/).filter(Boolean);
let taskWords = [];
for (const w of words) {
  if (w.startsWith('repo:')) {
    repo = w.replace(/^repo:/, '').trim();
  } else {
    taskWords.push(w);
  }
}
const contentText = taskWords.join(' ').trim();
const finalText = contentText || text;

// 4. Strict payload construction without legacy fields
const payload = {
  action: action,
  chat_id: chatId,
  preset: preset
};

if (repo) payload.repo = repo;
if (action === 'chat' || action === 'reject') {
  payload.message = finalText;
} else if (action === 'brainstorm' || action === 'execute_task') {
  payload.task = finalText;
}

return [{
  payload: payload,
  ui_text: finalText,
  is_chat: (action === 'chat')
}];

