const items = $input.all();
const results = [];
for (const item of items) {
  const json = item.json || {};
  let chatId = '';
  let isChat = false;
  try {
    const parsed = $('Parse Command').item.json;
    chatId = (parsed && parsed.payload && parsed.payload.chat_id) ? parsed.payload.chat_id : '';
    isChat = !!(parsed && parsed.is_chat);
  } catch (e) {
    chatId = json.chat_id || '';
  }
  results.push({
    json: {
      run_id: String(json.run_id || '').trim(),
      chat_id: String(chatId).trim(),
      is_chat: isChat,
      poll_attempt: 0,
      poll_limit: 180,
      status: json.status || 'QUEUED'
    }
  });
}
return results;

const items = $input.all();
const results = [];
for (const item of items) {
  const json = item.json || {};
  const runId = json.run_id || '';
  const status = String(json.status || '').toLowerCase();

  let pollAttempt = 0;
  let pollLimit = 180;
  let chatId = '';
  let isChat = false;

  try {
    const initCtx = $('Init Poll Context').item.json;
    pollAttempt = (json.poll_attempt !== undefined) ? json.poll_attempt : ((initCtx && initCtx.poll_attempt !== undefined) ? initCtx.poll_attempt : 0);
    pollLimit = (json.poll_limit !== undefined) ? json.poll_limit : ((initCtx && initCtx.poll_limit !== undefined) ? initCtx.poll_limit : 180);
    chatId = json.chat_id || (initCtx && initCtx.chat_id) || '';
    isChat = (json.is_chat !== undefined) ? json.is_chat : (initCtx ? !!initCtx.is_chat : false);
  } catch (e) {
    chatId = json.chat_id || '';
  }

  if (!runId || json.error) {
    results.push({
      json: {
        route: 'failed',
        run_id: runId,
        chat_id: chatId,
        is_chat: isChat,
        status: 'ERROR',
        error: json.error || 'Invalid response from /api/runs'
      }
    });
  } else if (status === 'completed') {
    results.push({
      json: {
        route: 'completed',
        run_id: runId,
        chat_id: chatId,
        is_chat: isChat,
        status: 'COMPLETED',
        result: json.result || null,
        progress: 100
      }
    });
  } else if (status === 'blocked_prerequisite') {
    const summary = (json.result && json.result.summary) || json.result || {};
    const blockerReason = json.error || summary.blocker_reason || 'Missing prerequisite for execution';
    results.push({
      json: {
        route: 'failed',
        run_id: runId,
        chat_id: chatId,
        is_chat: isChat,
        status: 'BLOCKED_PREREQUISITE',
        error: blockerReason,
        result: json.result || null
      }
    });
  } else if (status === 'failed' || status === 'error' || status === 'canceled') {
    results.push({
      json: {
        route: 'failed',
        run_id: runId,
        chat_id: chatId,
        is_chat: isChat,
        status: status.toUpperCase(),
        error: json.error || 'Execution failed',
        result: json.result || null
      }
    });
  } else if (pollAttempt >= pollLimit) {
    results.push({
      json: {
        route: 'timeout',
        run_id: runId,
        chat_id: chatId,
        is_chat: isChat,
        status: 'TIMEOUT',
        poll_attempt: pollAttempt
      }
    });
  } else {
    results.push({
      json: {
        route: 'continue_polling',
        run_id: runId,
        chat_id: chatId,
        is_chat: isChat,
        poll_attempt: pollAttempt + 1,
        poll_limit: pollLimit,
        status: status,
        progress: json.progress || 0
      }
    });
  }
}
return results;

// Estrazione e normalizzazione rigorosa di chat_id e message
const raw = $json.body || $json;
const rawChatId = (raw.chat_id !== undefined && raw.chat_id !== null) ? raw.chat_id : ((raw.chatId !== undefined && raw.chatId !== null) ? raw.chatId : (raw.data ? (raw.data.chat_id !== undefined ? raw.data.chat_id : raw.data.chatId) : undefined));
const message = (raw.message !== undefined && raw.message !== null) ? raw.message : (raw.data && raw.data.message !== undefined ? raw.data.message : '');
const event = raw.event || '';

// Filtro eventi tecnici o rumorosi che non devono essere inviati a Telegram
const IGNORED_EVENTS = ['token_warning', 'heartbeat', 'ping', 'debug'];
if (IGNORED_EVENTS.includes(event)) {
  return [{
    json: {
      deliver: false,
      chat_id: '',
      message: String(message),
      reason: 'ignored_technical_event'
    }
  }];
}

let deliver = false;
let chatIdStr = '';

if (rawChatId !== undefined && rawChatId !== null) {
  const str = String(rawChatId).trim();
  // Accetta ID Telegram validi: numeri interi positivi o negativi (es: 511090810, -1001234567890)
  if (/^-?\d+$/.test(str) && str !== '0') {
    chatIdStr = str;
    if (message && typeof message === 'string' && message.trim().length > 0) {
      deliver = true;
    }
  }
}

if (deliver) {
  return [{
    json: {
      deliver: true,
      chat_id: chatIdStr,
      message: String(message)
    }
  }];
} else {
  return [{
    json: {
      deliver: false,
      chat_id: chatIdStr,
      message: String(message),
      reason: !chatIdStr ? 'missing_or_invalid_chat_id' : 'empty_message'
    }
  }];
}
